mapper.insert:
INSERT INTO cireport(ciId,ciName,orderId)
    SELECT c.ciId,c.ciName,o.orderId FROM orders o JOIN setmealdetailed sd ON sd.smId=o.smId
    JOIN checkitem c ON c.ciId=sd.ciId WHERE o.orderId=#{orderId}

INSERT INTO cidetailedreport(name,unit,minrange,maxrange,normalValue,normalValueString,type,value,isError,ciId,orderId)
    SELECT d.name,d.unit,d.minrange,d.maxrange,d.normalValue,d.normalValueString,d.type,NULL,0,r.cirId,r.orderId
    FROM cireport r JOIN checkitemdetailed d ON d.ciId=r.ciId WHERE r.orderId=#{orderId}
